function useDemoQuery<T>(data: T) {
  const [value] = useState(data);
  return { data: value, isLoading: false, isError: false, refetch: async () => ({ data: value }) };
}
const useGetCareerOverview = () => useDemoQuery<{ userName: string; readiness: number; streak: number; completedToday: number; dailyGoal: number; recommendation: string; recentActivity: { id: string; title: string; meta: string; kind: string }[] }>({ userName: 'Player', readiness: 68, streak: 4, completedToday: 1, dailyGoal: 3, recommendation: 'Complete one focused proof rep for your target role.', recentActivity: [] });
const useGetCareerSignals = () => useDemoQuery<{ id: string; label: string; score: number; delta: number; category: string }[]>([{ id: 'focus', label: 'CS specialization', score: 78, delta: 8, category: 'direction' }, { id: 'skills', label: 'Technical skills', score: 64, delta: 6, category: 'proof' }, { id: 'target', label: 'Career target', score: 71, delta: 4, category: 'intent' }]);
const useListJobs = () => useDemoQuery(demoJobs);
const useListApplications = () => {
  const progress = useProgress();
  return { data: progress.applications as Application[], isLoading: false, isError: false, refetch: async () => ({ data: progress.applications as Application[] }) };
};
const useGetPracticeSummary = () => useDemoQuery<{ questionsSolved: number; accuracy: number; weeklyChange: number; topics: { label: string; score: number; questionCount: number }[]; nextPractice: { topic: string; difficulty: string; questions: number } }>({ questionsSolved: 24, accuracy: 72, weeklyChange: 12, topics: [], nextPractice: { topic: 'Data structures', difficulty: 'Medium', questions: 12 } });
const useGetResumeAnalysis = () => useDemoQuery({ score: 0, ats: 0, skills: 0, experience: 0, formatting: 0, strengths: [], improvements: [] });
const mutation = () => ({ isPending: false, mutate: (_variables: unknown, options?: { onSuccess?: () => void }) => options?.onSuccess?.() });
const useInteractWithJob = mutation;
const useCreateApplication = () => {
  const progress = useProgress();
  return { isPending: false, mutate: (variables: { data: Omit<Application, 'id' | 'date'> }, options?: { onSuccess?: () => void }) => {
    progress.recordApplication({ ...variables.data, id: `manual-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, date: new Date().toISOString().slice(0, 10) });
    options?.onSuccess?.();
  }};
};
const useUpdateApplication = () => {
  const progress = useProgress();
  return { isPending: false, mutate: (variables: { id: string; data: Partial<Application> }, options?: { onSuccess?: () => void }) => {
    progress.updateApplication(variables.id, variables.data);
    options?.onSuccess?.();
  }};
};
const getGetCareerSignalsQueryKey = () => ['demo-signals'];
const getListApplicationsQueryKey = () => ['demo-applications'];
