export function Discover() {
  const { user } = useAuth();
  const progress = useProgress();
  const { data, isLoading, isError, refetch } = useListJobs();
  const interact = useInteractWithJob();
  const queryClient = useQueryClient();
  const [index, setIndex] = useState(0);
  const [mode, setMode] = useState('all');
  const [search, setSearch] = useState('');
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [dragX, setDragX] = useState(0);
  const [feedback, setFeedback] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const pointerStart = useRef({ x: 0, active: false });
  const sourceJobs = data?.length ? data : demoJobs;
   const jobs = useMemo(() => {
    return sourceJobs
       .filter(job => `${job.role} ${job.company} ${job.location} ${job.skills.join(' ')}`.toLowerCase().includes(search.toLowerCase()) && (mode === 'all' || job.mode.toLowerCase() === mode));
   }, [sourceJobs, mode, search]);
  const current = jobs[index % Math.max(jobs.length, 1)];
  const action = (value: typeof JobInteractionInputAction[keyof typeof JobInteractionInputAction]) => {
    if (!current || interact.isPending) return;
    const label = value === JobInteractionInputAction.pass ? 'SIGNAL CLEARED' : value === JobInteractionInputAction.save ? 'QUEST SAVED' : value === JobInteractionInputAction['highly-interested'] ? 'PRIORITY FLAGGED' : 'INTEREST LOGGED';
    setFeedback(label);
    setDetailsOpen(false);
    setDragX(value === JobInteractionInputAction.pass ? -420 : 420);
    if (value === JobInteractionInputAction.interested || value === JobInteractionInputAction['highly-interested']) {
      progress.recordApplication({
        id: `role-${current.id}`, company: current.company, role: current.role, location: current.location,
        url: current.url, date: new Date().toISOString().slice(0, 10),
        status: 'applied', source: 'Discover Roles', match: current.match,
        nextAction: 'Review role details', notes: current.description,
      });
    }
    interact.mutate({ id: current.id, data: { action: value } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListJobsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetCareerSignalsQueryKey() }); } });
    window.setTimeout(() => { setIndex(i => i + 1); setDragX(0); setFeedback(''); }, 220);
  };
   const openCompanyWebsite = (company: string) => { const url = companyUrls[company]; if (url) window.open(url, '_blank', 'noopener,noreferrer'); };
   const reset = () => { setSearch(''); setMode('all'); setIndex(0); setFeedback(''); setDetailsOpen(false); };
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'ArrowLeft') { event.preventDefault(); action(JobInteractionInputAction.pass); }
    if (event.key === 'ArrowRight') { event.preventDefault(); action(JobInteractionInputAction.interested); }
    if (event.key === 'ArrowUp') { event.preventDefault(); action(JobInteractionInputAction['highly-interested']); }
  };
   return <div className="stagger space-y-7">
    <PageHeader eyebrow={`Role discovery / ${user?.path ?? 'live'} radar`} title="Choose the next quest." description={`Read the signal, inspect the loadout, then make a call. Every decision tunes your ${user?.path ?? 'career'} DNA.`} action={<div className="hud-chip"><span className="hud-dot" /> {data?.length ?? 0} live matches</div>} />
    <section className="discover-toolbar">
      <div className="relative min-w-0 flex-1"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" /><input data-testid="input-search-jobs" aria-label="Search roles" value={search} onChange={e => { setSearch(e.target.value); setIndex(0); }} placeholder="Search role, company, skill, or city" className="h-11 w-full rounded-md border border-border bg-card pl-9 pr-3 text-sm outline-none transition focus:ring-2 focus:ring-accent" /></div>
      <button data-testid="button-toggle-discover-filters" onClick={() => setShowFilters(value => !value)} className="button-secondary shrink-0"><SlidersHorizontal size={15} /> Filters</button>
      <div className={`${showFilters ? 'flex' : 'hidden'} absolute left-0 right-0 top-14 z-20 flex-wrap gap-2 border-2 border-border bg-card p-3 shadow-[4px_4px_0_var(--retro-purple)] sm:static sm:flex sm:border-0 sm:bg-transparent sm:p-0 sm:shadow-none`}>
        {['all', 'remote', 'hybrid', 'onsite'].map(item => <button data-testid={`button-filter-${item}`} key={item} onClick={() => { setMode(item); setIndex(0); setShowFilters(false); }} className={`${mode === item ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground'} rounded-md px-3 py-2 text-xs font-semibold capitalize transition-colors`}>{item}</button>)}
      </div>
    </section>
    {isLoading ? <div className="mx-auto max-w-2xl"><SkeletonCard /></div> : isError ? <ErrorState onRetry={refetch} /> : current ? <div className="discover-layout"><section className="min-w-0"><div className="discover-deck"><div className="discover-deck-meta"><span>ROLE SIGNAL {String(index + 1).padStart(2, '0')} / {String(jobs.length).padStart(2, '0')}</span><span>ARROWS OR DRAG TO DECIDE</span></div><div className="discover-card-stack"><div className="discover-back-card" /><div className="discover-back-card discover-back-card-two" /><div className="discover-card-wrap" style={{ transform: `translateX(${dragX}px) rotate(${dragX / 28}deg)`, opacity: dragX ? .72 : 1 }} onKeyDown={handleKeyDown} tabIndex={0} aria-label={`${current.role} at ${current.company}. Use left, right, or up arrow keys to decide.`} onPointerDown={event => { pointerStart.current.x = event.clientX; pointerStart.current.active = true; event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={event => { if (pointerStart.current.active) setDragX(Math.max(-160, Math.min(160, event.clientX - pointerStart.current.x))); }} onPointerUp={event => { if (!pointerStart.current.active) return; pointerStart.current.active = false; const delta = event.clientX - pointerStart.current.x; if (delta < -90) action(JobInteractionInputAction.pass); else if (delta > 90) action(JobInteractionInputAction.interested); else setDragX(0); }}><JobCard job={current} pending={interact.isPending} onAction={action} position={Math.min(index + 1, jobs.length)} total={jobs.length} onDetails={() => { openCompanyWebsite(current.company); setDetailsOpen(value => !value); }} detailsOpen={detailsOpen} /></div></div></div><div className="discover-actions" role="group" aria-label="Role decision actions"><button data-testid={`button-pass-job-${current.id}`} aria-label="Pass on this role" onClick={() => action(JobInteractionInputAction.pass)} disabled={interact.isPending} className="discover-action discover-action-pass"><X size={21} /></button><button data-testid={`button-save-job-${current.id}`} aria-label="Save this role" onClick={() => action(JobInteractionInputAction.save)} disabled={interact.isPending} className="discover-action discover-action-save"><Bookmark size={19} /> <span>Save</span></button><button data-testid={`button-priority-job-${current.id}`} aria-label="Mark this role as priority" onClick={() => action(JobInteractionInputAction['highly-interested'])} disabled={interact.isPending} className="discover-action discover-action-priority"><Star size={20} fill="currentColor" /></button><button data-testid={`button-interested-job-${current.id}`} aria-label="Show interest in this role" onClick={() => action(JobInteractionInputAction.interested)} disabled={interact.isPending} className="discover-action discover-action-interest"><Heart size={20} fill="currentColor" /></button></div><p className="discover-key-hint"><span>← pass</span><span>↑ priority</span><span>→ interested</span></p></section><aside className="discover-side-panel"><div className="retro-side-card"><div className="mb-4 flex items-center justify-between"><span className="pixel-label text-foreground/55">Decision console</span><Target size={17} className="text-accent" /></div><div className="grid grid-cols-3 gap-2"><div><p className="retro-side-value">{Math.min(index, jobs.length)}</p><p className="retro-side-label">scanned</p></div><div><p className="retro-side-value text-accent">{jobs.filter(job => job.match >= 85).length}</p><p className="retro-side-label">strong fit</p></div><div><p className="retro-side-value text-retro-purple">{Math.max(jobs.length - index, 0)}</p><p className="retro-side-label">remaining</p></div></div><div className="mt-5 h-2 bg-muted"><div className="h-full bg-accent transition-all duration-500" style={{ width: `${jobs.length ? Math.min((index / jobs.length) * 100, 100) : 0}%` }} /></div></div><div className="retro-side-card"><div className="mb-3 flex items-center gap-2"><Eye size={15} className="text-retro-cyan" /><span className="font-mono text-[10px] uppercase tracking-[.15em]">How to play</span></div><p className="text-sm leading-relaxed text-muted-foreground">Drag the card on touch or mouse. Open details before you commit. Your choices become useful signal, not noise.</p></div>{feedback && <div data-testid="status-discover-feedback" className="discover-feedback"><CheckCircle2 size={17} /> {feedback}</div>}<button data-testid="button-reset-discovery" onClick={reset} className="button-secondary w-full justify-center">Reset radar</button></aside></div> : <EmptyState icon={<Search size={22} />} title="No roles match that signal" text="Try widening your search or resetting the filters." action="Reset discovery" onAction={reset} />}
  </div>;
}

const dailyMissionDefinitions: { id: DailyMissionId; title: string; description: string; target: number; reward: number; icon: ReactNode }[] = [
  { id: 'warm-up-run', title: 'WARM-UP RUN', description: 'Complete 3 DSA questions', target: 3, reward: 25, icon: <Flame size={18} /> },
  { id: 'accuracy-strike', title: 'ACCURACY STRIKE', description: 'Get 2 DSA questions correct', target: 2, reward: 35, icon: <Target size={18} /> },
  { id: 'topic-explorer', title: 'TOPIC EXPLORER', description: 'Complete 5 questions from the same topic', target: 5, reward: 50, icon: <Compass size={18} /> },
];

function DailyMissionsBoard({ dailyMissions }: { dailyMissions: DailyMissions }) {
  const leadingTopic = Object.entries(dailyMissions.topicProgress).sort(([, first], [, second]) => second - first)[0]?.[0];
  return <section data-testid="daily-missions" className="rounded-xl border-2 border-primary bg-primary p-5 text-primary-foreground shadow-[5px_5px_0_var(--retro-purple)] sm:p-7">
    <div className="mb-6 flex flex-wrap items-end justify-between gap-3">
      <div>
        <p className="pixel-label text-accent">Practice lab / daily board</p>
        <h2 className="mt-2 text-2xl font-semibold tracking-[-.04em]">DAILY MISSIONS</h2>
        <p className="mt-2 text-sm text-primary-foreground/65">Complete today's missions to earn bonus leaderboard points.</p>
      </div>
      <span className="font-mono text-[10px] uppercase tracking-[.16em] text-primary-foreground/50">Local date · {dailyMissions.date}</span>
    </div>
    <div className="grid gap-3 md:grid-cols-3">
      {dailyMissionDefinitions.map(mission => {
        const value = Math.min(mission.target, dailyMissions.progress[mission.id]);
        const completed = dailyMissions.completed.includes(mission.id);
        return <article data-testid={`daily-mission-${mission.id}`} key={mission.id} className={`rounded-lg border p-4 transition-colors ${completed ? 'border-accent bg-accent/15' : 'border-primary-foreground/15 bg-primary-foreground/5'}`}>
          <div className="flex items-start justify-between gap-3">
            <div className={`grid h-9 w-9 place-items-center rounded-md ${completed ? 'bg-accent text-primary' : 'bg-primary-foreground/10 text-accent'}`}>{completed ? <Check size={18} /> : mission.icon}</div>
            <span className={`font-mono text-[10px] uppercase tracking-[.12em] ${completed ? 'text-accent' : 'text-primary-foreground/55'}`}>{completed ? '✓ COMPLETED' : 'IN PROGRESS'}</span>
          </div>
          <h3 className="mt-5 text-sm font-semibold tracking-[.04em]">{mission.title}</h3>
          <p className="mt-2 min-h-10 text-xs leading-relaxed text-primary-foreground/65">{mission.description}</p>
          {mission.id === 'topic-explorer' && <p className="mt-2 font-mono text-[10px] text-accent">{leadingTopic ? `Best run: ${leadingTopic}` : 'Pick any topic'}</p>}
          <div className="mt-5 flex items-center justify-between font-mono text-xs">
            <span>{value} / {mission.target}</span>
            <span className={completed ? 'text-accent' : 'text-primary-foreground/65'}>{completed ? `+${mission.reward} PTS CLAIMED` : `+${mission.reward} PTS`}</span>
          </div>
          <div className="mt-2 h-2 overflow-hidden rounded-full bg-primary-foreground/10" role="progressbar" aria-label={`${mission.title} progress`} aria-valuemin={0} aria-valuemax={mission.target} aria-valuenow={value}>
            <div className={`h-full rounded-full transition-all duration-500 ${completed ? 'bg-accent' : 'bg-primary-foreground/60'}`} style={{ width: `${(value / mission.target) * 100}%` }} />
          </div>
        </article>;
      })}
    </div>
  </section>;
}

 export function Practice() {
  const progress = useProgress();
  const [topic, setTopic] = useState('Arrays');
  const [difficulty, setDifficulty] = useState<'All' | 'Easy' | 'Medium' | 'Hard'>('All');
  const [session, setSession] = useState<DSAQuestion[] | null>(null);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [submitted, setSubmitted] = useState(false);
  const [sessionScore, setSessionScore] = useState(0);
  const [sessionResults, setSessionResults] = useState<{ topic: string; score: number; total: number; xp: number } | null>(null);
  const questionsSolved = progress.questionsAttempted;
  const accuracy = questionsSolved ? Math.round((progress.questionsCorrect / questionsSolved) * 100) : 0;
  const dsaProgress = Math.min(100, Math.round((questionsSolved / 45) * 100));
  const currentQuestion = session?.[questionIndex];
  const startPractice = () => { const selected = (dsaQuestionBank[topic] ?? []).filter(question => difficulty === 'All' || question.difficulty === difficulty); if (!selected.length) return; setSession(selected); setQuestionIndex(0); setSelectedAnswer(null); setSubmitted(false); setSessionScore(0); setSessionResults(null); };
  const submitAnswer = () => {
    if (selectedAnswer === null || !currentQuestion || submitted) return;
    const correct = selectedAnswer === currentQuestion.correctAnswer;
    progress.recordPracticeQuestion(currentQuestion, correct);
     const difficultyXP = currentQuestion.difficulty === 'Easy' ? 10 : currentQuestion.difficulty === 'Medium' ? 20 : 35;
     progress.addXP(difficultyXP, `answered ${topic} ${currentQuestion.difficulty}`, `question:${currentQuestion.id}`);
     if (correct) progress.addXP(5, `correct answer in ${topic}`, `question-correct:${currentQuestion.id}`);
    if (correct) setSessionScore(score => score + 1);
    setSubmitted(true);
  };
  const nextQuestion = () => {
    if (!session || !currentQuestion) return;
    const nextScore = sessionScore + (selectedAnswer === currentQuestion.correctAnswer ? 1 : 0);
    if (questionIndex + 1 < session.length) { setQuestionIndex(index => index + 1); setSelectedAnswer(null); setSubmitted(false); return; }
     const xp = difficulty === 'All' && session.length === 15 ? 50 : 0;
     if (xp > 0) progress.addXP(xp, `completed ${topic} topic`, `topic-complete:${topic}`);
    progress.recordPractice({
      topic,
      difficulty,
      completed: session.length,
      correct: nextScore,
      accuracy: Math.round((nextScore / session.length) * 100),
      xp,
    });
    progress.updateStreak();
    setSessionResults({ topic, score: nextScore, total: session.length, xp });
    setSession(null);
  };
   if (!session && !sessionResults) return <div className="stagger space-y-7"><PageHeader eyebrow="Practice lab / DSA" title="Train the signal." description="Choose a topic, filter the difficulty, and work through 15 real questions with immediate feedback." action={<button onClick={startPractice} className="button-primary"><Target size={16} /> Start practice</button>} /><DailyMissionsBoard dailyMissions={progress.dailyMissions} /><section className="rounded-xl border-2 border-accent bg-card p-6 shadow-[5px_5px_0_var(--retro-purple)] sm:p-8"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="pixel-label text-accent">Choose your arena</p><h2 className="mt-2 text-2xl font-semibold">DSA practice</h2><p className="mt-2 text-sm text-muted-foreground">Every topic has exactly 15 questions: 5 Easy, 5 Medium, 5 Hard.</p></div><div className="flex flex-wrap gap-2">{(['All', 'Easy', 'Medium', 'Hard'] as const).map(level => <button key={level} onClick={() => setDifficulty(level)} className={`${difficulty === level ? 'bg-primary text-primary-foreground' : 'border border-border bg-background'} rounded-md px-3 py-2 text-xs font-semibold`}>{level} · {level === 'All' ? 15 : 5}</button>)}</div></div><div className="mt-7 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">{practiceTopics.map(item => <button key={item} onClick={() => setTopic(item)} className={`${topic === item ? 'border-accent bg-accent/15' : 'border-border'} rounded-md border bg-background p-3 text-left text-xs font-semibold text-foreground hover:border-primary`}>{item}<span className="mt-1 block font-mono text-[9px] text-accent">15 questions</span></button>)}</div><button onClick={startPractice} className="button-primary mt-7"><Target size={16} /> Start {topic} · {difficulty}</button></section><section className="grid gap-4 md:grid-cols-3"><MetricTile label="Questions solved" value={questionsSolved} icon={<BookOpenCheck size={17} />} /><MetricTile label="Accuracy" value={`${accuracy}%`} icon={<BarChart3 size={17} />} /><MetricTile label="DSA progress" value={`${dsaProgress}%`} icon={<TrendingUp size={17} />} accent /></section><Card title="Progress signal" className="practice-hero bg-[#17172b] text-white [&_h2]:!text-black [&_p]:!text-black"><p className="font-mono text-[10px] uppercase tracking-[.18em] !text-black">Current run</p><h3 className="mb-3 mt-3 text-2xl font-semibold text-black">{progress.streak} day streak</h3><p className="mb-7 text-sm !text-black">{progress.questionsCorrect} correct answers across {questionsSolved} attempts.</p><button onClick={startPractice} className="inline-flex items-center gap-2 text-sm font-semibold text-accent">Begin {topic} <ArrowRight size={15} /></button></Card></div>;
   if (session && currentQuestion) return <div className="stagger space-y-7"><PageHeader eyebrow="DSA practice / live session" title="Make the rep count." description={`One answer at a time. Your result is saved when you finish this ${topic} set.`} action={<span className="hud-chip"><span className="hud-dot" /> Question {questionIndex + 1} / {session.length}</span>} /><DailyMissionsBoard dailyMissions={progress.dailyMissions} /><section className="rounded-xl border-2 border-primary bg-card p-6 shadow-[5px_5px_0_var(--retro-purple)] sm:p-9"><div className="mb-8 flex flex-wrap items-center justify-between gap-3"><div><p className="pixel-label text-accent">DSA practice</p><h2 className="mt-2 text-2xl font-semibold">{topic}</h2></div><span className="rounded-md border border-border px-3 py-2 font-mono text-xs">{currentQuestion.difficulty}</span></div><div className="mb-8 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full bg-accent transition-all" style={{ width: `${((questionIndex + 1) / session.length) * 100}%` }} /></div><p className="mb-6 max-w-3xl text-xl font-medium leading-relaxed">{currentQuestion.question}</p><div className="grid gap-3">{currentQuestion.options.map((option, index) => <button key={option} disabled={submitted} onClick={() => setSelectedAnswer(index)} className={`rounded-md border-2 p-4 text-left text-sm transition-colors ${selectedAnswer === index ? 'border-accent bg-accent/15' : 'border-border bg-background hover:border-primary'} ${submitted && index === currentQuestion.correctAnswer ? 'border-green-600 bg-green-500/10' : ''}`}><span className="mr-3 font-mono text-accent">{String.fromCharCode(65 + index)}.</span>{option}</button>)}</div>{submitted && <div className={`mt-7 rounded-md border p-5 ${selectedAnswer === currentQuestion.correctAnswer ? 'border-green-600/40 bg-green-500/10' : 'border-destructive/40 bg-destructive/10'}`}><p className="font-semibold">{selectedAnswer === currentQuestion.correctAnswer ? '✓ Correct' : '✕ Incorrect'}</p><p className="mt-4 font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Explanation</p><p className="mt-2 text-sm leading-relaxed">{currentQuestion.explanation}</p><p className="mt-4 text-xs text-muted-foreground">Correct answer: <strong>{currentQuestion.options[currentQuestion.correctAnswer]}</strong> · Time: {currentQuestion.timeComplexity} · Space: {currentQuestion.spaceComplexity}</p></div>}<div className="mt-8 flex justify-end">{submitted ? <button data-testid="button-next-question" onClick={nextQuestion} className="button-primary">{questionIndex + 1 === session.length ? 'Finish session' : 'Next question'} <ArrowRight size={15} /></button> : <button data-testid="button-submit-answer" disabled={selectedAnswer === null} onClick={submitAnswer} className="button-primary">Submit answer <Check size={15} /></button>}</div></section></div>;
   if (sessionResults) { const resultAccuracy = Math.round((sessionResults.score / sessionResults.total) * 100); return <div className="stagger space-y-7"><PageHeader eyebrow="DSA practice / results" title="DSA practice complete." description="The rep is logged. Your next session starts from this stronger baseline." /><DailyMissionsBoard dailyMissions={progress.dailyMissions} /><section className="rounded-xl border-2 border-primary bg-primary p-7 text-primary-foreground shadow-[5px_5px_0_var(--retro-coral)] sm:p-10"><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">Session cleared</p><h2 className="mt-3 text-3xl font-semibold">{sessionResults.score} / {sessionResults.total}</h2><div className="mt-8 grid gap-5 sm:grid-cols-3"><div><p className="font-mono text-[10px] uppercase text-primary-foreground/50">Accuracy</p><p className="mt-2 text-2xl font-semibold">{resultAccuracy}%</p></div><div><p className="font-mono text-[10px] uppercase text-primary-foreground/50">XP earned</p><p className="mt-2 text-2xl font-semibold text-accent">+{sessionResults.xp} XP</p></div><div><p className="font-mono text-[10px] uppercase text-primary-foreground/50">Topic practiced</p><p className="mt-2 text-2xl font-semibold">{sessionResults.topic}</p></div></div><div className="mt-8"><p className="mb-2 text-sm">Performance</p><ProgressBar value={resultAccuracy} tone="teal" /></div></section><div className="flex flex-wrap gap-3"><button data-testid="button-practice-again" onClick={startPractice} className="button-primary">Practice again <RefreshCw size={15} /></button><button data-testid="button-back-to-practice" onClick={() => setSessionResults(null)} className="button-secondary">Back to practice</button><Link data-testid="link-view-roadmap" href="/interview-roadmap" className="button-secondary">View roadmap <ArrowRight size={15} /></Link></div></div>; }
   return <div className="stagger space-y-7"><PageHeader eyebrow="Practice lab / DSA" title="Train the signal." description="Choose a topic, filter the difficulty, and work through 15 real questions with immediate feedback." action={<button data-testid="button-start-practice" onClick={startPractice} className="button-primary"><Target size={16} /> Start DSA practice</button>} /><section className="rounded-xl border-2 border-accent bg-card p-6 shadow-[5px_5px_0_var(--retro-purple)] sm:p-8"><div className="flex flex-col gap-6 lg:flex-row lg:items-end lg:justify-between"><div><p className="pixel-label text-accent">Choose your arena</p><h2 className="mt-2 text-2xl font-semibold">DSA practice</h2><p className="mt-2 max-w-xl text-sm text-muted-foreground">Choose a topic and difficulty. Every topic contains 15 questions: 5 Easy, 5 Medium, and 5 Hard.</p></div><button data-testid="button-start-dsa-practice" onClick={startPractice} className="button-primary shrink-0"><Target size={16} /> Start DSA practice</button></div><div className="mt-7 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-6">{practiceTopics.map(item => <button key={item} onClick={() => setTopic(item)} className={`rounded-md border px-3 py-3 text-left text-xs font-medium ${topic === item ? 'border-accent bg-accent/15 text-foreground' : 'border-border bg-background text-muted-foreground'} hover:border-primary`}>{item}<span className="mt-1 block font-mono text-[9px] text-accent">15 questions</span></button>)}</div></section><section className="grid gap-4 md:grid-cols-3"><MetricTile label="Questions solved" value={questionsSolved} icon={<BookOpenCheck size={17} />} /><MetricTile label="Accuracy" value={`${accuracy}%`} icon={<BarChart3 size={17} />} /><MetricTile label="DSA progress" value={`${dsaProgress}%`} icon={<TrendingUp size={17} />} accent /></section><div className="grid gap-4 lg:grid-cols-[1.35fr_.65fr]"><Card title="Topic performance"><div className="space-y-5">{Object.entries(progress.topics).length ? Object.entries(progress.topics).map(([label, score]) => { const value = score.attempted ? Math.round((score.correct / score.attempted) * 100) : 0; return <div data-testid={`topic-score-${label.toLowerCase().replaceAll(' ', '-')}`} key={label}><div className="mb-2 flex justify-between text-sm"><span className="font-medium">{label}</span><span className="font-mono text-xs text-muted-foreground">{value}% <span className="font-sans">· {score.attempted} reps</span></span></div><ProgressBar value={value} tone={value >= 75 ? 'teal' : 'yellow'} /></div>; }) : <EmptyState icon={<BarChart3 size={20} />} title="No practice data yet" text="Start a DSA set to see topic accuracy here." action="Start DSA practice" onAction={startPractice} />}</div></Card><Card title="Progress signal" className="practice-hero bg-[#17172b] text-white [&_h2]:!text-black [&_p]:!text-black"><div className="mb-5 inline-flex rounded-md bg-accent/15 p-2 text-accent"><Target size={18} /></div><p className="font-mono text-[10px] uppercase tracking-[.18em] !text-black">CURRENT RUN</p><h3 className="mb-3 mt-3 text-2xl font-semibold tracking-[-.04em] !text-black">{progress.streak} day streak</h3><p className="mb-7 text-sm !text-black">{progress.questionsCorrect} correct answers across {questionsSolved} attempts.</p><button onClick={startPractice} className="inline-flex items-center gap-2 text-sm font-semibold text-accent">Begin {topic} <ArrowRight size={15} /></button></Card></div><Card title="Recent movement"><div className="space-y-3">{progress.activities.filter(activity => activity.type === 'practice').slice(0, 5).map(activity => <div key={activity.id} className="rounded-md bg-muted/45 px-4 py-3 text-sm"><div className="flex flex-wrap items-center gap-x-3 gap-y-1"><strong>{activity.practice?.topic ?? activity.message}</strong>{activity.practice && <span className="font-mono text-xs text-muted-foreground">{activity.practice.difficulty} · {activity.practice.completed}/{activity.practice.completed} completed · {activity.practice.accuracy}% accuracy · +{activity.practice.xp} XP</span>}</div><span className="mt-1 block text-xs text-muted-foreground">{new Date(activity.timestamp).toLocaleString()}</span></div>)}{!progress.activities.some(activity => activity.type === 'practice') && <div className="flex items-center justify-between gap-4"><p className="text-sm text-muted-foreground">Your completed practice sets will show here.</p><Link href="/practice" className="text-xs font-semibold text-primary">Start DSA practice <ArrowRight size={14} className="inline" /></Link></div>}</div></Card></div>;
}

export function Resume() {
  const query = useGetResumeAnalysis();
  if (query.isLoading) return <PageLoading title="Reading your resume signal" />;
  if (query.isError) return <ErrorState onRetry={() => query.refetch()} />;
  const data = query.data;
  const metrics = data ? [{ label: 'ATS readiness', value: data.ats }, { label: 'Skills coverage', value: data.skills }, { label: 'Experience', value: data.experience }, { label: 'Formatting', value: data.formatting }] : [];
  return <div className="stagger space-y-7"><PageHeader eyebrow="Resume studio" title="Make your experience legible." description="Your resume is a product surface. Give the right evidence a better signal." action={<button data-testid="button-upload-resume" className="button-primary"><Upload size={16} /> Upload new resume</button>} /><section className="grid gap-4 md:grid-cols-[.7fr_1.3fr]"><div className="rounded-xl bg-primary p-6 text-primary-foreground sm:p-8"><div className="mb-10 flex items-center justify-between"><span className="font-mono text-[10px] uppercase tracking-[.18em] text-white/70">Overall score</span><FileCheck2 className="text-accent" size={19} /></div><div data-testid="text-resume-score" className="mb-3 text-7xl font-semibold tracking-[-.08em]">{data?.score ?? '—'}<span className="text-2xl text-accent">/100</span></div><p className="max-w-xs text-sm leading-relaxed text-primary-foreground/60">A strong base. Sharpen the evidence and you will read as more senior than your years.</p><div className="mt-10 h-1.5 rounded-full bg-primary-foreground/10"><div className="h-full rounded-full bg-accent" style={{ width: `${data?.score ?? 0}%` }} /></div></div><Card title="Signal breakdown"><div className="grid gap-x-8 gap-y-6 sm:grid-cols-2">{metrics.map(metric => <div data-testid={`resume-metric-${metric.label.toLowerCase().replaceAll(' ', '-')}`} key={metric.label}><div className="mb-2 flex justify-between text-sm"><span>{metric.label}</span><span className="font-mono text-xs">{metric.value}%</span></div><ProgressBar value={metric.value} tone={metric.value >= 75 ? 'teal' : 'yellow'} /></div>)}{!metrics.length && <EmptyState icon={<FileText size={20} />} title="Upload your first resume" text="We will score the signal, not the formatting theater." action="Upload resume" />}</div></Card></section><div className="grid gap-4 lg:grid-cols-2"><Card title="What is already working" icon={<Check size={16} className="text-accent" />}>{data?.strengths?.length ? <ul className="space-y-3">{data.strengths.map((item, i) => <li data-testid={`resume-strength-${i}`} key={item} className="flex gap-3 text-sm leading-relaxed"><span className="mt-1 text-accent">+</span>{item}</li>)}</ul> : <p className="text-sm text-muted-foreground">Your strengths will appear after your resume is analyzed.</p>}</Card><Card title="High-leverage edits" icon={<Lightbulb size={16} className="text-accent" />}>{data?.improvements?.length ? <ul className="space-y-3">{data.improvements.map((item, i) => <li data-testid={`resume-improvement-${i}`} key={item} className="flex gap-3 text-sm leading-relaxed"><span className="mt-1 text-destructive">↗</span>{item}</li>)}</ul> : <p className="text-sm text-muted-foreground">No edits queued yet.</p>}</Card></div></div>;
}

export function Applications() {
  const query = useListApplications();
  const { clearApplications } = useProgress();
  const create = useCreateApplication();
  const update = useUpdateApplication();
  const queryClient = useQueryClient();
  const [showAdd, setShowAdd] = useState(false);
  const [statusFilter, setStatusFilter] = useState('all');
  const [form, setForm] = useState({ company: '', role: '', match: '72', status: 'applied', nextAction: 'Follow up in 5 days' });
  const applications = (query.data ?? []).filter(item => statusFilter === 'all' || item.status.toLowerCase() === statusFilter);
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate({ data: { company: form.company, role: form.role, match: Number(form.match), status: form.status, nextAction: form.nextAction } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListApplicationsQueryKey() }); setShowAdd(false); setForm({ company: '', role: '', match: '72', status: 'applied', nextAction: 'Follow up in 5 days' }); } }); };
  const clearAll = () => { if (window.confirm('Clear all applications? This cannot be undone.')) clearApplications(); };
  const moveStatus = (item: Application) => { const next = item.status.toLowerCase() === 'applied' ? 'screening' : item.status.toLowerCase() === 'screening' ? 'interview' : 'offer'; update.mutate({ id: item.id, data: { status: next } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListApplicationsQueryKey() }) }); };
  if (query.isLoading) return <PageLoading title="Loading your applications" />;
  if (query.isError) return <ErrorState onRetry={() => query.refetch()} />;
  return <div className="stagger space-y-7"><PageHeader eyebrow="Application tracker" title="Keep the thread." description="A calm place to know what is moving, what is waiting, and what needs you next." action={<div className="flex flex-wrap gap-2"><button data-testid="button-clear-applications" onClick={clearAll} className="button-secondary">Clear</button><button data-testid="button-add-application" onClick={() => setShowAdd(true)} className="button-primary"><Plus size={16} /> Add application</button></div>} /><div className="flex flex-wrap gap-2">{['all', 'applied', 'screening', 'interview', 'offer'].map(status => <button data-testid={`button-status-filter-${status}`} key={status} onClick={() => setStatusFilter(status)} className={`${statusFilter === status ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground'} rounded-md px-3 py-2 text-xs font-medium capitalize`}>{status}</button>)}</div>{applications.length ? <div className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"><div className="hidden grid-cols-[1.2fr_1.2fr_.55fr_.7fr_1fr_auto] gap-4 border-b border-border bg-muted/45 px-5 py-3 font-mono text-[10px] uppercase tracking-wider text-muted-foreground md:grid"><span>Company</span><span>Role</span><span>Match</span><span>Applied</span><span>Next action</span><span /></div><div className="divide-y divide-border">{applications.map(item => <div data-testid={`application-row-${item.id}`} key={item.id} className="grid gap-3 px-5 py-5 md:grid-cols-[1.2fr_1.2fr_.55fr_.7fr_1fr_auto] md:items-center md:gap-4"><div><div className="flex items-center gap-2 font-semibold"><span className="grid h-7 w-7 place-items-center rounded bg-primary text-[10px] text-primary-foreground">{item.company.slice(0, 2).toUpperCase()}</span>{item.company}</div><div className="mt-1 text-xs text-muted-foreground md:hidden">{item.role}</div></div><div className="hidden text-sm text-muted-foreground md:block">{item.role}</div><div><span className="font-mono text-sm text-accent">{item.match}%</span><div className="mt-1 h-1 w-14 rounded-full bg-muted"><div className="h-full rounded-full bg-accent" style={{ width: `${item.match}%` }} /></div></div><div className="text-xs text-muted-foreground">{item.date}</div><div className="text-sm text-muted-foreground"><span className={`mr-2 inline-block h-1.5 w-1.5 rounded-full ${item.status.toLowerCase() === 'offer' ? 'bg-accent' : 'bg-primary/40'}`} />{item.nextAction}</div><button data-testid={`button-progress-application-${item.id}`} onClick={() => moveStatus(item)} disabled={update.isPending} className="justify-self-end rounded-md border border-border p-2 text-muted-foreground hover:bg-muted hover:text-primary" title="Move to next stage" style={item.status.toLowerCase() === 'offer' ? { visibility: 'hidden' } : undefined}><ArrowRight size={15} /></button></div>)}</div></div> : <EmptyState icon={<BriefcaseBusiness size={22} />} title="Your tracker is clear" text="Add the first role you want to keep a thread on." action="Add application" onAction={() => setShowAdd(true)} />}{showAdd && <ApplicationModal form={form} setForm={setForm} onClose={() => setShowAdd(false)} onSubmit={submit} pending={create.isPending} />}</div>;
}

export function SoftSkills() {
  return <div className="stagger space-y-7"><PageHeader eyebrow="Career development" title="Build your soft skills." description="Sharpen the communication, teamwork, and leadership signals that matter once you're in the room." /><Card title="Soft Skills & Communication" icon={<MessageSquare size={17} />}><div className="grid gap-4 md:grid-cols-2">{softSkillsResources.map(resource => <article key={resource.title} className="rounded-lg border border-border bg-muted/25 p-5"><p className="mb-3 flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[.18em] text-accent"><Users size={12} /> {resource.category}</p><h3 className="mb-2 text-lg font-semibold tracking-[-.03em]">{resource.title}</h3><p className="mb-5 text-sm leading-relaxed text-muted-foreground">{resource.description}</p><a href={resource.url} target="_blank" rel="noreferrer" className="button-secondary inline-flex items-center gap-2" data-testid={`button-open-resource-${resource.title.toLowerCase().replaceAll(' ', '-')}`}>Open Resource <ArrowUpRight size={15} /></a></article>)}</div></Card></div>;
}

export function DSA() {
  return <div className="stagger space-y-7"><PageHeader eyebrow="Technical preparation" title="Level up your DSA." description="Build the problem-solving skills you need for coding interviews with focused practice and learning resources." /><Card title="DSA Learning Resources" icon={<Youtube size={17} />}><div className="grid gap-4 md:grid-cols-2">{practiceResources.map(resource => <article key={resource.category} className="rounded-lg border border-border bg-muted/25 p-5"><p className="mb-3 font-mono text-[10px] uppercase tracking-[.18em] text-accent">{resource.category}</p><h3 className="mb-2 text-lg font-semibold tracking-[-.03em]">{resource.title}</h3><p className="mb-5 text-sm leading-relaxed text-muted-foreground">{resource.description}</p><a href={resource.url} target="_blank" rel="noreferrer" className="button-secondary inline-flex items-center gap-2" data-testid={`button-open-resource-${resource.category.toLowerCase().replaceAll(' ', '-')}`}>Open Resource <ArrowUpRight size={15} /></a></article>)}</div></Card></div>;
}

export function Profile() {
  const { user, updateProfile } = useAuth();
  const [saved, setSaved] = useState(false);
  const [form, setForm] = useState(user ?? { name: '', email: '', city: '', field: '', path: '', skillLevel: '', goal: '' });
  const edit = (key: Exclude<keyof CareerProfile, 'skills'>, value: string) => setForm(current => ({ ...current, [key]: value }));
  const editSkills = (value: string) => setForm(current => ({ ...current, skills: value.split(',').map(skill => skill.trim()).filter(Boolean) }));
  const save = (event: FormEvent) => { event.preventDefault(); updateProfile({ ...form, path: form.specialization || form.path, skillLevel: form.programmingLevel || form.skillLevel, goal: form.target || form.goal }); setSaved(true); window.setTimeout(() => setSaved(false), 1800); };
  const avatar = form.name.split(' ').map(part => part[0]).slice(0, 2).join('').toUpperCase() || 'CO';
   return <div className="stagger space-y-7"><PageHeader eyebrow="PLAYER PROFILE / CHARACTER SHEET" title="Your playable career character." description="Tune every answer from the character forge. Your dashboard reacts immediately." action={saved ? <span className="flex items-center gap-2 text-sm font-medium text-accent"><Check size={16} /> Saved locally</span> : undefined} /><div className="grid gap-4 lg:grid-cols-[.7fr_1.3fr]"><section className="rounded-xl bg-primary p-6 text-primary-foreground sm:p-8"><div data-testid="profile-avatar" className="mb-8 grid h-16 w-16 place-items-center rounded-full border-2 border-accent bg-accent text-xl font-semibold text-primary shadow-[4px_4px_0_var(--retro-coral)]">{avatar}</div><p className="mb-2 font-mono text-[10px] uppercase tracking-[.18em] text-accent">{form.className ?? user?.className ?? 'CODE APPRENTICE'}</p><h2 data-testid="text-profile-name" className="text-2xl font-semibold tracking-[-.04em] !text-black">{form.name || 'Unnamed player'}</h2><p data-testid="text-profile-class" className="mt-1 text-sm text-white/70">{form.specialization || form.path || 'Still Exploring'} · {form.programmingLevel || form.skillLevel || 'Unranked'}</p><div className="mt-10 border-t border-primary-foreground/10 pt-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] !text-black/45">Character loadout</p><div className="mt-4 space-y-3 text-xs text-primary-foreground/70"><p><span className="text-accent">CAREER TARGET</span> {form.target || form.goal || 'Not set'}</p><div className="flex flex-wrap gap-2"><span className="text-accent">SKILLS</span>{form.skills?.length ? form.skills.map(skill => <span className="border border-primary-foreground/20 px-2 py-1" key={skill}>{skill}</span>) : <span>Not set</span>}</div></div></div></section><form onSubmit={save} className="rounded-xl border border-border bg-card p-6 shadow-sm sm:p-8"><div className="mb-7 flex items-center justify-between"><h2 className="text-lg font-semibold tracking-[-.03em]">EDIT CHARACTER</h2><UserRound size={18} className="text-muted-foreground" /></div><div className="grid gap-5 sm:grid-cols-2"><Field id="profile-name" label="Full name" value={form.name} onChange={value => edit('name', value)} /><Field id="profile-email" label="Email" value={form.email} onChange={value => edit('email', value)} /><Field id="profile-city" label="Based in" value={form.city} onChange={value => edit('city', value)} /><Field id="profile-specialization" label="CS specialization" value={form.specialization ?? ''} onChange={value => edit('specialization', value)} /><Field id="profile-programming-level" label="Programming level" value={form.programmingLevel ?? ''} onChange={value => edit('programmingLevel', value)} /><Field id="profile-target" label="Career target" value={form.target ?? ''} onChange={value => edit('target', value)} /><Field id="profile-skills" label="Technical skills (comma-separated)" value={(form.skills ?? []).join(', ')} onChange={editSkills} /><Field id="profile-field" label="Legacy field" value={form.field} onChange={value => edit('field', value)} /><Field id="profile-path" label="Legacy career path" value={form.path} onChange={value => edit('path', value)} /><Field id="profile-skill-level" label="Legacy skill level" value={form.skillLevel} onChange={value => edit('skillLevel', value)} /><Field id="profile-goal" label="Legacy career goal" value={form.goal} onChange={value => edit('goal', value)} /></div><button data-testid="button-save-profile" className="button-primary mt-8"><Check size={16} /> Save character</button></form></div></div>;
}

export function SettingsPage() {
  const [settings, setSettings] = useState({ digest: true, nudges: true, weekly: false, visibility: true });
  return <div className="stagger space-y-7"><PageHeader eyebrow="Settings" title="Set the pace." description="Career progress is personal. Tune the system to keep it useful, not noisy." /><div className="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><Card title="Notifications" icon={<Bell size={16} className="text-accent" />}><div className="divide-y divide-border">{[['digest', 'Daily briefing', 'One concise view of your next best actions.'], ['nudges', 'Action nudges', 'A gentle note when something important is waiting.'], ['weekly', 'Weekly reflection', 'A Sunday snapshot of the signals you are building.']].map(([key, title, text]) => <ToggleRow key={key} title={title} text={text} enabled={settings[key as keyof typeof settings]} onToggle={() => setSettings({ ...settings, [key]: !settings[key as keyof typeof settings] })} id={`toggle-${key}`} />)}</div></Card><Card title="Privacy & visibility" icon={<Settings2 size={16} className="text-accent" />}><ToggleRow id="toggle-visibility" title="Private by default" text="Your profile and activity stay visible only to you." enabled={settings.visibility} onToggle={() => setSettings({ ...settings, visibility: !settings.visibility })} /><div className="mt-7 border-t border-border pt-6"><p className="mb-3 text-sm font-medium">Account access</p><button data-testid="button-manage-access" className="flex w-full items-center justify-between rounded-md border border-border px-3 py-3 text-left text-sm hover:bg-muted"><span className="flex items-center gap-2"><LockKeyhole size={15} className="text-muted-foreground" /> Manage sign-in methods</span><ArrowRight size={15} /></button></div></Card></div><div className="rounded-xl border border-destructive/20 bg-destructive/5 p-5"><p className="text-sm font-semibold text-destructive">Need a reset?</p><p className="mt-1 text-sm text-muted-foreground">Clear your recommendation signals without deleting your application history.</p><button data-testid="button-reset-signals" className="mt-4 rounded-md border border-destructive/25 px-3 py-2 text-xs font-semibold text-destructive hover:bg-destructive/10">Reset recommendation signals</button></div></div>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="retro-page-header flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-2 font-mono text-[10px] uppercase tracking-[.2em] text-accent"><span className="mr-2 text-primary/40">01</span>{eyebrow}</div><h1 className="text-3xl font-semibold tracking-[-.055em] sm:text-[2.6rem]">{title}</h1><p className="mt-2 max-w-xl text-sm leading-relaxed text-muted-foreground">{description}</p></div>{action && <div className="shrink-0">{action}</div>}</div>;
}

function Card({ title, icon, action, children, className = '' }: { title: string; icon?: ReactNode; action?: ReactNode; children: ReactNode; className?: string }) {
  return <section className={`retro-card rounded-xl border border-border bg-card p-5 shadow-sm sm:p-6 ${className}`}><div className="mb-6 flex items-center justify-between"><h2 className="flex items-center gap-2 text-sm font-semibold tracking-[-.01em]">{icon}{title}</h2>{action}</div>{children}</section>;
}

function SignalRow({ label, value, delta, category, large = false }: { label: string; value: number; delta: number; category: string; large?: boolean }) {
  return <div data-testid={`signal-row-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="mb-2 flex items-center justify-between gap-3"><div><span className={large ? 'text-base font-medium' : 'text-sm font-medium'}>{label}</span><span className="ml-2 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">{category}</span></div><div className="flex items-center gap-2"><span className="font-mono text-xs">{value}</span><span className={`flex items-center gap-0.5 font-mono text-[10px] ${delta >= 0 ? 'text-teal-700 dark:text-teal-300' : 'text-destructive'}`}>{delta >= 0 ? <ArrowUpRight size={11} /> : <ArrowDownRight size={11} />}{Math.abs(delta)}%</span></div></div><ProgressBar value={value} tone={delta >= 0 ? 'teal' : 'yellow'} /></div>;
}
function ProgressBar({ value, tone = 'yellow' }: { value: number; tone?: 'yellow' | 'teal' }) { return <div className="h-2 overflow-hidden rounded-full bg-muted"><div className={`${tone === 'teal' ? 'bg-[#287d78]' : 'bg-accent'} h-full rounded-full transition-all duration-700`} style={{ width: `${Math.max(0, Math.min(value, 100))}%` }} /></div>; }
function MetricTile({ label, value, icon, accent }: { label: string; value: string | number; icon: ReactNode; accent?: boolean }) { return <div className={`retro-metric rounded-xl border border-border ${accent ? 'bg-accent/15' : 'bg-card'} p-5 shadow-sm`}><div className="mb-7 flex items-center justify-between"><span className="text-xs text-muted-foreground">{label}</span><span className={accent ? 'text-accent-foreground' : 'text-accent'}>{icon}</span></div><div data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`} className="text-3xl font-semibold tracking-[-.06em]">{value}</div><div className="mt-3 h-1 w-9 bg-accent" /></div>; }
function MiniJob({ job }: { job: Job }) { return <div data-testid={`mini-job-${job.id}`}><div className="mb-5 flex items-start justify-between"><div><div className="mb-1 text-xs text-muted-foreground">{job.company}</div><h3 className="text-xl font-semibold tracking-[-.04em] text-black">{job.role}</h3></div><span className="rounded-full bg-accent/20 px-2.5 py-1 font-mono text-xs text-accent-foreground">{job.match}%</span></div><div className="mb-6 space-y-2 text-sm text-muted-foreground"><div className="flex items-center gap-2"><MapPin size={14} /> {job.location} · {job.mode}</div><div className="font-mono text-xs text-accent">{job.salary}</div></div><Link data-testid={`link-mini-job-${job.id}`} href="/discover" className="inline-flex items-center gap-2 text-sm font-semibold text-primary">View role <ArrowRight size={15} /></Link></div>; }
function JobCard({ job, onAction, pending, position, total, onDetails, detailsOpen }: { job: Job; onAction: (action: typeof JobInteractionInputAction[keyof typeof JobInteractionInputAction]) => void; pending: boolean; position: number; total: number; onDetails: () => void; detailsOpen: boolean }) {
     return <div className="retro-job relative overflow-hidden rounded-2xl border border-border bg-card shadow-md">
    <div className="retro-job-strip flex items-center justify-between border-b border-border px-5 py-4"><span className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Role {position} of {total} // unlocked</span><span className="flex items-center gap-1.5 rounded-full bg-accent/15 px-2.5 py-1 font-mono text-xs font-medium text-accent-foreground"><Star size={12} fill="currentColor" /> {job.match}% match</span></div>
     <div className="p-6 sm:p-9"><div className="mb-9 flex items-start justify-between gap-5"><div><p className="mb-2 font-mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">quest sponsor / {job.company}</p><h2 data-testid={`text-job-role-${job.id}`} className="text-3xl font-semibold tracking-[-.06em] sm:text-4xl">{job.role}</h2></div><div className="grid h-12 w-12 shrink-0 place-items-center rounded-lg bg-primary text-sm font-semibold text-primary-foreground shadow-[3px_3px_0_var(--retro-purple)]">{job.badge ?? job.company.slice(0, 2).toUpperCase()}</div></div>
      <div className="mb-7 grid gap-3 border-y border-border py-5 text-sm sm:grid-cols-3"><div><span className="mb-1 block font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Location</span><span>{job.location}</span></div><div><span className="mb-1 block font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Work mode</span><span>{job.mode}</span></div><div><span className="mb-1 block font-mono text-[10px] uppercase tracking-wider text-muted-foreground">Compensation</span><span>{job.salary}</span></div></div>
      <p className="mb-6 text-sm leading-relaxed text-muted-foreground">{job.description}</p><div className="mb-6 flex flex-wrap gap-2">{job.skills.map(skill => <span key={skill} className="rounded-md bg-muted px-2.5 py-1.5 text-xs">{skill}</span>)}</div>
       <button data-testid={`button-view-details-${job.id}`} onPointerDown={event => event.stopPropagation()} onClick={event => { event.stopPropagation(); onDetails(); }} className="job-details-toggle"><Eye size={15} /> View role brief <ArrowRight size={14} /></button>
      {detailsOpen && <div data-testid={`job-details-${job.id}`} className="job-details-panel"><div><span className="job-details-label">Signal note</span><p>Strong overlap with your current skill map. The fastest proof point is a small shipped project you can explain end to end.</p></div><div><span className="job-details-label">Posted</span><p>{job.posted || 'Recently posted'} · recruiter signal is active</p></div></div>}
      {pending && <div className="mt-5 flex items-center justify-center gap-2 font-mono text-[10px] uppercase tracking-[.15em] text-muted-foreground"><Loader2 size={14} className="animate-spin" /> Recording decision</div>}
    </div>
  </div>;
}
function EmptyState({ icon, title, text, action, href, onAction }: { icon: ReactNode; title: string; text: string; action: string; href?: string; onAction?: () => void }) { const content = <>{icon}<span>{action}</span><ArrowRight size={14} /></>; return <div className="flex min-h-[150px] flex-col items-center justify-center px-5 py-8 text-center"><div className="mb-3 text-accent">{icon}</div><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 max-w-sm text-xs leading-relaxed text-muted-foreground">{text}</p>{href ? <Link data-testid={`link-empty-${action.toLowerCase().replaceAll(' ', '-')}`} href={href} className="mt-5 inline-flex items-center gap-2 text-xs font-semibold text-primary">{content}</Link> : <button data-testid={`button-empty-${action.toLowerCase().replaceAll(' ', '-')}`} onClick={onAction} className="mt-5 inline-flex items-center gap-2 text-xs font-semibold text-primary">{content}</button>}</div>; }
function InfoCard({ icon, title, text, action, href }: { icon: ReactNode; title: string; text: string; action: string; href: string }) { return <Link data-testid={`link-info-${title.toLowerCase()}`} href={href} className="rounded-xl border border-border bg-card p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="mb-7 grid h-8 w-8 place-items-center rounded-md bg-accent/20 text-accent-foreground">{icon}</div><h3 className="mb-2 font-semibold">{title}</h3><p className="mb-5 text-sm leading-relaxed text-muted-foreground">{text}</p><span className="flex items-center gap-2 text-xs font-semibold">{action} <ArrowRight size={14} /></span></Link>; }
function ToggleRow({ id, title, text, enabled, onToggle }: { id: string; title: string; text: string; enabled: boolean; onToggle: () => void }) { return <div className="flex items-center justify-between gap-5 py-4"><div><p className="text-sm font-medium">{title}</p><p className="mt-1 max-w-sm text-xs leading-relaxed text-muted-foreground">{text}</p></div><button data-testid={id} aria-pressed={enabled} onClick={onToggle} className={`${enabled ? 'bg-accent' : 'bg-muted'} relative h-6 w-11 shrink-0 rounded-full transition-colors`}><span className={`${enabled ? 'translate-x-6 bg-primary' : 'translate-x-1 bg-muted-foreground/60'} absolute left-0 top-1 h-4 w-4 rounded-full transition-transform`} /></button></div>; }
function Field({ id, label, value, onChange }: { id: string; label: string; value: string; onChange: (value: string) => void }) { return <label className="block"><span className="mb-2 block text-xs font-medium text-muted-foreground">{label}</span><input data-testid={`input-${id}`} value={value} onChange={event => onChange(event.target.value)} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm outline-none transition focus:border-accent focus:ring-2 focus:ring-accent/20" /></label>; }
function ApplicationModal({ form, setForm, onClose, onSubmit, pending }: { form: { company: string; role: string; match: string; status: string; nextAction: string }; setForm: (form: { company: string; role: string; match: string; status: string; nextAction: string }) => void; onClose: () => void; onSubmit: (event: FormEvent) => void; pending: boolean }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-primary/40 p-4"><div className="w-full max-w-lg rounded-xl border border-border bg-card p-6 shadow-xl sm:p-8"><div className="mb-7 flex items-start justify-between"><div><div className="mb-2 font-mono text-[10px] uppercase tracking-[.18em] text-accent">New thread</div><h2 className="text-2xl font-semibold tracking-[-.04em] !text-black">Add an application</h2></div><button data-testid="button-close-application-modal" onClick={onClose} className="rounded-md p-2 text-muted-foreground hover:bg-muted"><X size={18} /></button></div><form onSubmit={onSubmit} className="space-y-4"><Field id="application-company" label="Company" value={form.company} onChange={company => setForm({ ...form, company })} /><Field id="application-role" label="Role" value={form.role} onChange={role => setForm({ ...form, role })} /><div className="grid gap-4 sm:grid-cols-2"><Field id="application-match" label="Match score" value={form.match} onChange={match => setForm({ ...form, match })} /><label><span className="mb-2 block text-xs font-medium text-muted-foreground">Status</span><select data-testid="select-application-status" value={form.status} onChange={event => setForm({ ...form, status: event.target.value })} className="h-10 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="applied">Applied</option><option value="screening">Screening</option><option value="interview">Interview</option></select></label></div><Field id="application-next-action" label="Next action" value={form.nextAction} onChange={nextAction => setForm({ ...form, nextAction })} /><div className="flex justify-end gap-2 pt-4"><button data-testid="button-cancel-application" type="button" onClick={onClose} className="button-secondary">Cancel</button><button data-testid="button-submit-application" disabled={pending || !form.company || !form.role} className="button-primary">{pending ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} />} Add thread</button></div></form></div></div>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={`pulse-line rounded-md bg-muted ${className}`} />; }
function SkeletonCard() { return <div className="rounded-xl border border-border bg-card p-8"><Skeleton className="mb-6 h-3 w-24" /><Skeleton className="mb-4 h-8 w-3/4" /><Skeleton className="mb-8 h-4 w-1/2" /><Skeleton className="mb-3 h-2 w-full" /><Skeleton className="h-24 w-full" /></div>; }
function RowsSkeleton({ count }: { count: number }) { return <div className="space-y-6">{Array.from({ length: count }, (_, i) => <div key={i}><div className="mb-2 flex justify-between"><Skeleton className="h-3 w-1/3" /><Skeleton className="h-3 w-10" /></div><Skeleton className="h-2 w-full" /></div>)}</div>; }
function PageLoading({ title }: { title: string }) { return <div className="space-y-7"><div><Skeleton className="mb-3 h-3 w-28" /><Skeleton className="h-11 w-72" /><Skeleton className="mt-3 h-4 w-96 max-w-full" /></div><div className="grid gap-4 md:grid-cols-3"><Skeleton className="h-32" /><Skeleton className="h-32" /><Skeleton className="h-32" /></div><div className="rounded-xl border border-border bg-card p-7"><p className="mb-4 font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">{title}</p><Skeleton className="h-3 w-full" /><Skeleton className="mt-4 h-3 w-4/5" /></div></div>; }
function ErrorState({ onRetry }: { onRetry: () => void }) { return <div className="flex min-h-[52vh] flex-col items-center justify-center text-center"><div className="mb-4 grid h-12 w-12 place-items-center rounded-full bg-destructive/10 text-destructive"><CircleHelp size={22} /></div><h2 className="text-xl font-semibold tracking-[-.03em]">That signal got lost</h2><p className="mt-2 max-w-sm text-sm leading-relaxed text-muted-foreground">We could not load this part of your workspace. Your work is safe; try the connection again.</p><button data-testid="button-retry" onClick={onRetry} className="button-secondary mt-6"><RefreshCw size={15} /> Try again</button></div>; }
function CompassIcon() { return <Compass size={16} />; }




